AbortController is used:

{noformat}  private async makeFetch(req: HttpRequest): Promise<Response> {
    const controller = new AbortController();

    const timeoutHandle = setTimeout(() => controller.abort(), req.opts?.timeout);
    const fetchOptions: RequestInit = {
      method: req.http_method,
      headers: req.headers,
      signal: controller.signal,
    };

    if (req.body) {
      fetchOptions.body = req.body;
    }

    const response = await fetch(req.url.toString(), fetchOptions);

    clearTimeout(timeoutHandle);

    return response;
  }
{noformat}

